fun {motive} ctorIdx =>
  bif Nat.ble ctorIdx 0 then PULift.{u, u} ((a : Real) → motive (Bhola.Tree.leaf a))
  else PULift.{u, u} ((a a_1 : Bhola.Tree) → motive (Bhola.Tree.node a a_1))

fun xs =>
  have h := HDiv.hDiv.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} (List.length.{0} xs) 1) 2;
  Bhola.pair (List.take.{0} h xs) (List.drop.{0} h xs)

fun add xs =>
  have h := HDiv.hDiv.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} (List.length.{0} xs) 1) 2;
  Bhola.pairValues add (List.take.{0} h xs) (List.drop.{0} h xs)
